-- 206: Original BrillaPrep WASSCE BrillaPrep transitional Leatherwork beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_206_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_206_guard;
INSERT INTO _migration_206_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_013' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_3' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does an edge beveller remove from a cut leather edge?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A measured strip that becomes the seam allowance for assembly","B. A shallow groove that locates a line of recessed stitches","C. A broad taper from the flesh side where two layers will overlap","D. A narrow sharp corner so the edge can be rounded and finished"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The edge beveller pares a small consistent arris from the grain or flesh corner, allowing sanding and burnishing to form a comfortable rounded profile. Therefore the correct answer is D: A narrow sharp corner so the edge can be rounded and finished.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_013' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_206_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_014' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_3' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why should a scratch awl be used with light pressure when tracing a pattern?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A shallow visible line guides cutting without weakening or deeply scarring the leather","B. A deep channel is needed so the cutting knife cannot move away from the pattern","C. Heavy scoring is preferred because shallow marks can be difficult to follow under workshop lighting","D. A row of full-depth holes gives the same result as an accurate cutting line"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A controlled awl line must remain readable but shallow, because deep scoring can become a visible defect or create a stress line beside a finished edge. Therefore the correct answer is A: A shallow visible line guides cutting without weakening or deeply scarring the leather.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_014' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_206_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_015' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_3' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What maintenance best preserves a sharp leather-cutting tool between uses?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Clean and dry the blade, protect the edge and store it in a fixed safe place","B. Leave dried contact adhesive on the bevel as a temporary protective coating","C. Rest the cutting edge directly on the bench so the tool cannot roll","D. Store the blade with damp sharpening residue to reduce later honing time"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Removing residue and moisture protects the steel, while an edge guard and designated storage position prevent accidental contact and damage to the sharpened bevel. Therefore the correct answer is A: Clean and dry the blade, protect the edge and store it in a fixed safe place.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_015' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_206_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_leatherwork_b004_016' AND NOT (q.topic_id IS 'topic_was_leatherwork_b004_4' AND q.subject_id IS 'subj_wassce_leatherwork' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a seam allowance added outside the finished outline of a leather pattern?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Mark the portion that should be skived away across its full width","B. Compensate for colour variation by making the visible panel larger","C. Replace the need to specify the finished dimensions of the article","D. Provide material for the selected stitched, folded or bonded joint"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The allowance supplies joint width beyond the finished line, preserving the required product dimensions after edges are folded, bonded or stitched together. Therefore the correct answer is D: Provide material for the selected stitched, folded or bonded joint.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_leatherwork_b004_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_leatherwork_b004_016' AND NOT (r.batch_id IS 'wassce-visual-arts-beta-004' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Leatherwork practice aligned to WAEC Ghana examiner evidence and Ghana curriculum sources; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_013', 'topic_was_leatherwork_b004_3', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What does an edge beveller remove from a cut leather edge?', 'multiple_choice', NULL, '["A. A measured strip that becomes the seam allowance for assembly","B. A shallow groove that locates a line of recessed stitches","C. A broad taper from the flesh side where two layers will overlap","D. A narrow sharp corner so the edge can be rounded and finished"]', 'D', 'The edge beveller pares a small consistent arris from the grain or flesh corner, allowing sanding and burnishing to form a comfortable rounded profile. Therefore the correct answer is D: A narrow sharp corner so the edge can be rounded and finished.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_3', 'Identify', 'AO1', NULL, NULL, 'board_waec');
