INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_015', 'topic_was_leatherwork_b004_3', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'What maintenance best preserves a sharp leather-cutting tool between uses?', 'multiple_choice', NULL, '["A. Clean and dry the blade, protect the edge and store it in a fixed safe place","B. Leave dried contact adhesive on the bevel as a temporary protective coating","C. Rest the cutting edge directly on the bench so the tool cannot roll","D. Store the blade with damp sharpening residue to reduce later honing time"]', 'A', 'Removing residue and moisture protects the steel, while an edge guard and designated storage position prevent accidental contact and damage to the sharpened bevel. Therefore the correct answer is A: Clean and dry the blade, protect the edge and store it in a fixed safe place.', 'hard', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_3', 'Identify', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_leatherwork_b004_016', 'topic_was_leatherwork_b004_4', 'subj_wassce_leatherwork', 'exam_wassce', NULL, NULL, 'Why is a seam allowance added outside the finished outline of a leather pattern?', 'multiple_choice', NULL, '["A. Mark the portion that should be skived away across its full width","B. Compensate for colour variation by making the visible panel larger","C. Replace the need to specify the finished dimensions of the article","D. Provide material for the selected stitched, folded or bonded joint"]', 'D', 'The allowance supplies joint width beyond the finished line, preserving the required product dimensions after edges are folded, bonded or stitched together. Therefore the correct answer is D: Provide material for the selected stitched, folded or bonded joint.', 'easy', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_leatherwork_b004_4', 'Explain', 'AO1', NULL, NULL, 'board_waec');
